import React, { Component } from 'react';
import '../css/CartModalComponent.css';

const formatCurrency = (value) => `${Number(value || 0).toLocaleString('vi-VN')}đ`;

const orderStatusLabels = {
  PENDING: 'Chờ xác nhận',
  APPROVED: 'Đang chế biến',
  COOKING: 'Đang chế biến',
  COMPLETED: 'Hoàn thành',
  CANCELLED: 'Đã hủy',
  CANCELED: 'Đã hủy'
};

const paymentStatusLabels = {
  PAID: 'Đã thanh toán',
  UNPAID: 'Chưa thanh toán'
};

class CartModalComponent extends Component {
  renderCartItem = (item, index) => {
    const itemTotal = Number(item.totalPrice || item.price * item.quantity || 0);
    return (
      <article key={`${item._id}-${index}`} className="cart-item-card">
        <div className="cart-item-topline">
          <div className="cart-item-name">{item.name}</div>
          <strong>{formatCurrency(itemTotal)}</strong>
        </div>
        <div className="cart-item-detail-row">
          <span>{item.quantity} phần × {formatCurrency(item.price)}</span>
        </div>
        {item.selectedToppings && Object.entries(item.selectedToppings).map(([name, quantity]) => (
          <div key={name} className="cart-item-detail-row cart-item-extra">
            <span>{name} × {quantity}</span>
          </div>
        ))}
        {item.note && <div className="cart-item-note">Ghi chú: {item.note}</div>}
      </article>
    );
  };

  renderOrder = (order) => {
    const status = order.status || 'PENDING';
    const paymentStatus = order.paymentStatus || 'UNPAID';
    return (
      <article key={order._id} className="customer-order-card">
        <div className="customer-order-card-heading">
          <div>
            <strong>Đơn #{String(order._id).slice(-6).toUpperCase()}</strong>
            <span>{order.cdate ? new Date(order.cdate).toLocaleString('vi-VN') : ''}</span>
          </div>
          <span className={`order-status-pill ${status.toLowerCase()}`}>
            {orderStatusLabels[status] || status}
          </span>
        </div>
        <div className="customer-order-meta">
          <span>{order.tableNo || 'Mang về'}</span>
          <span className={`payment-status-pill ${paymentStatus.toLowerCase()}`}>
            {paymentStatusLabels[paymentStatus] || paymentStatus}
          </span>
        </div>
        <div className="customer-order-items">
          {(order.items || []).map((item, index) => (
            <div key={`${order._id}-${index}`} className="customer-order-item-row">
              <span>{item.product?.name || 'Món ăn'} × {item.quantity || 1}</span>
              <span>{formatCurrency((Number(item.price || item.product?.price || 0) + Number(item.toppingTotal || 0)) * Number(item.quantity || 1))}</span>
            </div>
          ))}
        </div>
        {order.voucherCode && (
          <div className="customer-order-voucher">Mã đã dùng: {order.voucherCode} · giảm {formatCurrency(order.discountAmount)}</div>
        )}
        <div className="customer-order-total-row">
          {Number(order.discountAmount || 0) > 0 && <span>Tiết kiệm {formatCurrency(order.discountAmount)}</span>}
          <strong>{formatCurrency(order.total)}</strong>
        </div>
      </article>
    );
  };

  render() {
    const {
      cart, customerOrders = [], loadingCustomerOrders, vouchers = [], selectedVoucher,
      voucherInput, voucherError, subtotal, discountAmount, totalAfterDiscount,
      onVoucherInputChange, onApplyVoucher, onSelectVoucher, onClose, onSubmitOrder,
      isSubmittingOrder
    } = this.props;

    return (
      <div className="cart-modal-overlay" onMouseDown={(event) => {
        if (event.target === event.currentTarget) onClose();
      }}>
        <section className="cart-modal-card" role="dialog" aria-modal="true" aria-labelledby="cart-modal-title">
          <header className="cart-modal-header">
            <div>
              <span className="cart-modal-eyebrow">Nhà hàng Văn Lang</span>
              <h2 id="cart-modal-title">Món đã gọi</h2>
            </div>
            <button className="cart-modal-close" type="button" onClick={onClose} aria-label="Đóng">×</button>
          </header>

          <div className="cart-modal-body">
            <section className="cart-section">
              <div className="cart-section-heading">
                <div>
                  <h3>Giỏ món hiện tại</h3>
                  <span>{cart.length ? `${cart.length} món chờ gửi bếp` : 'Thêm món rồi gửi bếp khi bạn sẵn sàng'}</span>
                </div>
              </div>
              {cart.length > 0 ? cart.map(this.renderCartItem) : (
                <div className="cart-empty-state">
                  <span aria-hidden="true">🍽</span>
                  <strong>Chưa có món mới</strong>
                  <p>Các đơn bạn đã gọi vẫn được lưu ở phần lịch sử bên dưới.</p>
                </div>
              )}
            </section>

            {cart.length > 0 && (
              <section className="voucher-section">
                <div className="cart-section-heading">
                  <div>
                    <h3>Mã ưu đãi</h3>
                    <span>Chọn mã còn hiệu lực hoặc nhập mã của bạn</span>
                  </div>
                </div>
                <div className="voucher-entry-row">
                  <input
                    type="text"
                    value={voucherInput}
                    onChange={(event) => onVoucherInputChange(event.target.value)}
                    onKeyDown={(event) => { if (event.key === 'Enter') onApplyVoucher(); }}
                    placeholder="Nhập mã giảm giá"
                    aria-label="Nhập mã giảm giá"
                  />
                  <button type="button" onClick={onApplyVoucher}>Áp dụng</button>
                </div>
                {voucherError && <p className="voucher-error" role="alert">{voucherError}</p>}
                {vouchers.length > 0 ? (
                  <div className="voucher-list">
                    {vouchers.map(voucher => (
                      <button
                        type="button"
                        key={voucher._id}
                        className={`voucher-option ${selectedVoucher?.code === voucher.code ? 'selected' : ''}`}
                        onClick={() => onSelectVoucher(voucher)}
                      >
                        <span className="voucher-code">{voucher.code}</span>
                        <span className="voucher-description">
                          {voucher.title || (voucher.discountType === 'percent' ? `Giảm ${voucher.discount}%` : `Giảm ${formatCurrency(voucher.discount)}`)}
                          {Number(voucher.minOrder || 0) > 0 && ` · Đơn từ ${formatCurrency(voucher.minOrder)}`}
                        </span>
                        <span className="voucher-check" aria-hidden="true">{selectedVoucher?.code === voucher.code ? '✓' : '+'}</span>
                      </button>
                    ))}
                  </div>
                ) : <p className="voucher-empty">Hiện chưa có mã ưu đãi khả dụng.</p>}
              </section>
            )}

            <section className="customer-order-history">
              <div className="cart-section-heading">
                <div>
                  <h3>Lịch sử đơn hàng</h3>
                  <span>Theo dõi trạng thái món ngay tại đây</span>
                </div>
                <span className="order-history-count">{customerOrders.length}</span>
              </div>
              {loadingCustomerOrders ? <p className="history-loading">Đang tải đơn hàng…</p> : null}
              {!loadingCustomerOrders && customerOrders.length === 0 && (
                <div className="history-empty">Bạn chưa có đơn hàng nào.</div>
              )}
              <div className="customer-order-list">{customerOrders.map(this.renderOrder)}</div>
            </section>
          </div>

          <footer className="cart-modal-footer">
            <div className="cart-total-lines">
              <div><span>Tạm tính</span><span>{formatCurrency(subtotal)}</span></div>
              {Number(discountAmount || 0) > 0 && (
                <div className="cart-discount-line"><span>Giảm giá {selectedVoucher ? `(${selectedVoucher.code})` : ''}</span><span>−{formatCurrency(discountAmount)}</span></div>
              )}
              <div className="cart-grand-total"><strong>Tổng thanh toán</strong><strong>{formatCurrency(totalAfterDiscount)}</strong></div>
            </div>
            <button
              className="btn-submit-order"
              type="button"
              onClick={onSubmitOrder}
              disabled={isSubmittingOrder || cart.length === 0}
            >
              {isSubmittingOrder ? 'Đang gửi bếp…' : cart.length ? `Gửi bếp · ${formatCurrency(totalAfterDiscount)}` : 'Chưa có món để gửi'}
            </button>
          </footer>
        </section>
      </div>
    );
  }
}

export default CartModalComponent;
